import React from "react";
import { formatLabel } from "../../lib/reportData";
const StatusBadge = ({ status }) => {
  return (
    <span className={`status status-${status.toLowerCase()}`}>
      <i />
      {formatLabel(status)}
    </span>
  );
};
export default StatusBadge;
